// Shadertoy Fragment Shader
// Paste into https://www.shadertoy.com/new

#define PI 3.14159265359

mat2 rot(float a)
{
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float ringPattern(vec2 p, float t)
{
    float r = length(p);
    float a = atan(p.y, p.x);

    // Spiral distortion
    float spiral = sin(18.0 * r - 6.0 * a + t * 3.0);

    // Concentric pulse
    float rings = sin(40.0 * r - t * 5.0);

    // Angular spokes
    float spokes = sin(12.0 * a + sin(r * 8.0 - t) * 2.0);

    return spiral * 0.45 + rings * 0.35 + spokes * 0.20;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float t = iTime;

    // Zoom breathing
    float zoom = 1.0 + 0.15 * sin(t * 0.9);
    uv *= zoom;

    // Slowly rotate the whole field
    uv *= rot(t * 0.25);

    // Radial warp for hypnotic pull
    float r = length(uv);
    float warp = 0.08 * sin(10.0 * r - t * 3.0);
    uv += normalize(uv + 0.0001) * warp;

    float v = ringPattern(uv, t);

    // Convert pattern to sharp hypnotic bands
    float bands = smoothstep(-0.15, 0.15, sin(v * 5.0));

    // Extra center pulse
    float pulse = sin(30.0 * r - t * 8.0);
    bands += 0.18 * pulse / (1.0 + r * 4.0);

    // Psychedelic color cycling
    vec3 col;
    col.r = 0.5 + 0.5 * sin(6.0 * bands + t * 1.7 + 0.0);
    col.g = 0.5 + 0.5 * sin(6.0 * bands + t * 1.7 + 2.1);
    col.b = 0.5 + 0.5 * sin(6.0 * bands + t * 1.7 + 4.2);

    // Dark vignette for tunnel effect
    float vignette = smoothstep(1.4, 0.15, r);
    col *= vignette;

    // Bright center glow
    col += vec3(0.25, 0.15, 0.5) * exp(-r * 5.0);

    fragColor = vec4(col, 1.0);
}
```

